<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/app/bootstrap.php';

$staffPortalUrl = learning_platform_url('/admin/');
if (preg_match('#^https?://#i', $staffPortalUrl) === 1 && !is_learning_platform_host()) {
    header('Location: ' . $staffPortalUrl, true, 302);
    exit;
}

use App\Middleware\AdminMiddleware\AdminMiddleware;
use App\Models\Course\Course;
use App\Models\Lesson\Lesson;
use App\Models\Assignment\Assignment;
use App\Models\AssignmentSubmission\AssignmentSubmission;
use App\Models\Quiz\Quiz;
use App\Models\Certificate\Certificate;
use App\Controllers\CourseController\CourseController;
use App\Models\NewsletterSubscriber\NewsletterSubscriber;
use App\Models\LearningUser\LearningUser;
use App\Models\SiteSettings\SiteSettings;
use App\Models\PageContent\PageContent;
use App\Services\FirebaseService\FirebaseService;
use App\Services\FirestoreService\FirestoreService;

$middleware = new AdminMiddleware();
start_app_session();
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
$message = '';
$error = false;
$view = isset($_GET['view']) && $_GET['view'] === 'login' ? 'login' : 'dashboard';
$tab = isset($_GET['tab']) && in_array($_GET['tab'], ['overview', 'inquiries', 'public-submissions', 'users', 'instructors', 'subscribers', 'courses', 'enrollments', 'payments', 'lessons', 'quizzes', 'assignments', 'submissions', 'activity', 'certificates', 'pages', 'settings'], true) ? $_GET['tab'] : 'overview';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!isset($_POST['csrf_token'], $_SESSION['csrf_token']) || !hash_equals($_SESSION['csrf_token'], (string) $_POST['csrf_token'])) {
        http_response_code(419);
        $message = 'Your form expired. Refresh and try again.';
        $error = true;
    } elseif (($_POST['action'] ?? '') === 'logout') {
        $middleware->logout();
        header('Location: /admin/?view=login');
        exit;
    } elseif ($middleware->authenticated()) {
        try {
            $firestore = new FirestoreService(FirebaseService::firestore());
            $action = (string) ($_POST['action'] ?? '');
            if ($action === 'close' && isset($_POST['inquiry_id'])) {
                $firestore->update('contact_inquiries', (string) $_POST['inquiry_id'], ['status' => 'closed', 'updatedAt' => new DateTimeImmutable('now', new DateTimeZone('UTC'))]);
                $message = 'Enquiry marked as closed.';
            } elseif ($action === 'delete' && isset($_POST['inquiry_id'])) {
                $firestore->delete('contact_inquiries', (string) $_POST['inquiry_id']);
                $message = 'Enquiry deleted.';
            } elseif ($action === 'update-public-submission' && isset($_POST['collection'], $_POST['submission_id'], $_POST['status'])) {
                $collections = ['academy_event_registrations', 'academy_webinar_registrations', 'academy_job_applications', 'academy_scholarship_applications', 'academy_partner_inquiries', 'academy_accessibility_reports'];
                $collection = is_string($_POST['collection']) ? $_POST['collection'] : '';
                $submissionId = is_string($_POST['submission_id']) ? $_POST['submission_id'] : '';
                $submissionStatus = is_string($_POST['status']) ? $_POST['status'] : '';
                if (!in_array($collection, $collections, true) || !preg_match('/^[A-Za-z0-9_-]{1,150}$/', $submissionId) || !in_array($submissionStatus, ['contacted', 'reviewing', 'closed'], true)) throw new RuntimeException('Invalid public submission update.');
                if (!$firestore->get($collection, $submissionId)) throw new RuntimeException('Public submission was not found.');
                $firestore->update($collection, $submissionId, ['status' => $submissionStatus, 'reviewedAt' => new DateTimeImmutable('now', new DateTimeZone('UTC'))]);
                $tab = 'public-submissions';
                $message = 'Public submission status updated.';
            } elseif ($action === 'unsubscribe' && isset($_POST['subscriber_email'])) {
                NewsletterSubscriber::unsubscribe($firestore, (string) $_POST['subscriber_email']);
                $tab = 'subscribers';
                $message = 'Subscriber has been unsubscribed.';
            } elseif ($action === 'set-user-role' && isset($_POST['user_id'], $_POST['role'])) {
                LearningUser::setRole($firestore, is_string($_POST['user_id']) ? $_POST['user_id'] : '', is_string($_POST['role']) ? $_POST['role'] : '');
                $tab = 'users';
                $message = 'Account role updated.';
            } elseif ($action === 'set-user-status' && isset($_POST['user_id'], $_POST['status'])) {
                LearningUser::setStatus($firestore, is_string($_POST['user_id']) ? $_POST['user_id'] : '', is_string($_POST['status']) ? $_POST['status'] : '');
                $tab = 'users';
                $message = 'Account access updated.';
            } elseif ($action === 'save-site-settings') {
                [$settingsData, $validationErrors] = SiteSettings::validate($_POST);
                $tab = 'settings';
                if ($validationErrors) {
                    $message = reset($validationErrors);
                    $error = true;
                } else {
                    SiteSettings::save($firestore, $settingsData);
                    $message = 'Website and platform settings saved.';
                }
            } elseif ($action === 'save-page-content') {
                $tab = 'pages';
                $pageKey = is_string($_POST['page_key'] ?? null) ? $_POST['page_key'] : '';
                $validationErrors = PageContent::save($firestore, $pageKey, $_POST);
                if ($validationErrors) {
                    $message = reset($validationErrors);
                    $error = true;
                } else {
                    $message = 'Page introduction saved.';
                }
            } elseif ($action === 'save-course') {
                [$course, $validationErrors] = Course::validate($_POST);
                if (!$validationErrors) {
                    $course['catalogueId'] = '';
                    $titleKey = mb_strtolower($course['title']);
                    foreach (Course::catalogue() as $starterCourse) {
                        if (mb_strtolower((string) $starterCourse['title']) === $titleKey) {
                            $slug = strtolower(trim((string) preg_replace('/[^A-Za-z0-9]+/', '-', $starterCourse['title']), '-'));
                            $course['catalogueId'] = 'starter-' . $slug;
                            break;
                        }
                    }
                    foreach ($firestore->list('academy_courses', 100, 'title', 'ASCENDING') as $existingCourse) {
                        if (mb_strtolower((string) ($existingCourse['title'] ?? '')) === $titleKey && (string) ($existingCourse['id'] ?? '') !== (string) ($_POST['course_id'] ?? '')) {
                            $validationErrors['title'] = 'A course with this title is already managed. Edit that course instead.';
                            break;
                        }
                    }
                }
                if (!$validationErrors && $course['instructorId'] !== '') {
                    $instructor = $firestore->get('academy_users', $course['instructorId']);
                    if (!$instructor || ($instructor['role'] ?? '') !== 'instructor') $validationErrors['instructor_id'] = 'Choose an active instructor account.';
                    else $course['instructorName'] = (string) ($instructor['name'] ?? 'Instructor');
                } else $course['instructorName'] = '';
                if ($validationErrors) {
                    $tab = 'courses';
                    $message = reset($validationErrors);
                    $error = true;
                } elseif (!empty($_POST['course_id'])) {
                    $courseId = (string) $_POST['course_id'];
                    if (!$firestore->get('academy_courses', $courseId)) throw new RuntimeException('Course record was not found.');
                    $firestore->update('academy_courses', $courseId, $course);
                    $tab = 'courses';
                    $message = 'Course changes saved.';
                } else {
                    $firestore->add('academy_courses', $course);
                    $tab = 'courses';
                    $message = 'Course added to the catalogue.';
                }
            } elseif ($action === 'unpublish-course' && isset($_POST['course_id'])) {
                $firestore->update('academy_courses', (string) $_POST['course_id'], ['published' => false]);
                $tab = 'courses';
                $message = 'Course removed from the public catalogue.';
            } elseif ($action === 'enrollment-status' && isset($_POST['enrollment_id'], $_POST['status'])) {
                $enrollmentId = is_string($_POST['enrollment_id']) ? $_POST['enrollment_id'] : '';
                $enrollmentStatus = is_string($_POST['status']) ? $_POST['status'] : '';
                if (!preg_match('/^[a-f0-9]{64}$/', $enrollmentId) || !in_array($enrollmentStatus, ['approved', 'rejected'], true)) {
                    throw new RuntimeException('Invalid course request update.');
                }
                if (!$firestore->get('academy_enrollments', $enrollmentId)) throw new RuntimeException('Course request was not found.');
                $firestore->update('academy_enrollments', $enrollmentId, ['status' => $enrollmentStatus, 'reviewedAt' => new DateTimeImmutable('now', new DateTimeZone('UTC'))]);
                $tab = 'enrollments';
                $message = $enrollmentStatus === 'approved' ? 'Course request approved.' : 'Course request declined.';
            } elseif ($action === 'save-lesson') {
                [$lessonData, $validationErrors] = Lesson::validate($_POST);
                $tab = 'lessons';
                if ($validationErrors) {
                    $message = reset($validationErrors);
                    $error = true;
                } else {
                    $validCourses = (new CourseController())->index();
                    $selectedCourse = null;
                    foreach ($validCourses as $candidate) if (($candidate['id'] ?? '') === $lessonData['courseId']) { $selectedCourse = $candidate; break; }
                    if (!$selectedCourse) throw new RuntimeException('Choose a currently published course.');
                    $lessonData['courseTitle'] = (string) $selectedCourse['title'];
                    $editId = isset($_POST['lesson_id']) && is_string($_POST['lesson_id']) && $_POST['lesson_id'] !== '' ? $_POST['lesson_id'] : null;
                    Lesson::save($firestore, $lessonData, $editId);
                    $message = $editId ? 'Lesson changes saved.' : 'Lesson added.';
                }
            } elseif ($action === 'lesson-publish' && isset($_POST['lesson_id'], $_POST['published'])) {
                $lessonId = is_string($_POST['lesson_id']) ? $_POST['lesson_id'] : '';
                if (!preg_match('/^[A-Za-z0-9_-]{1,150}$/', $lessonId) || !in_array((string) $_POST['published'], ['0', '1'], true)) throw new RuntimeException('Invalid lesson update.');
                $firestore->update('academy_lessons', $lessonId, ['published' => $_POST['published'] === '1']);
                $tab = 'lessons';
                $message = $_POST['published'] === '1' ? 'Lesson published.' : 'Lesson unpublished.';
            } elseif ($action === 'save-quiz') {
                [$quizData, $validationErrors] = Quiz::validate($_POST);
                $tab = 'quizzes';
                if ($validationErrors) {
                    $message = reset($validationErrors);
                    $error = true;
                } else {
                    $lesson = $firestore->get('academy_lessons', $quizData['lessonId']);
                    if (!$lesson) throw new RuntimeException('The selected lesson was not found.');
                    foreach ($firestore->listByField('academy_quizzes', 'lessonId', $quizData['lessonId'], 10) as $existingQuiz) {
                        if (($existingQuiz['id'] ?? '') !== ($_POST['quiz_id'] ?? null)) throw new RuntimeException('This lesson already has a quiz. Edit the existing quiz instead.');
                    }
                    $quizData['courseId'] = (string) ($lesson['courseId'] ?? '');
                    $quizData['courseTitle'] = (string) ($lesson['courseTitle'] ?? 'Course');
                    $quizData['lessonTitle'] = (string) ($lesson['title'] ?? 'Lesson');
                    $editId = isset($_POST['quiz_id']) && is_string($_POST['quiz_id']) && $_POST['quiz_id'] !== '' ? $_POST['quiz_id'] : null;
                    Quiz::save($firestore, $quizData, $editId);
                    $message = $editId ? 'Quiz changes saved.' : 'Quiz added.';
                }
            } elseif ($action === 'quiz-publish' && isset($_POST['quiz_id'], $_POST['published'])) {
                $quizId = is_string($_POST['quiz_id']) ? $_POST['quiz_id'] : '';
                if (!preg_match('/^[A-Za-z0-9_-]{1,150}$/', $quizId) || !in_array((string) $_POST['published'], ['0', '1'], true)) throw new RuntimeException('Invalid quiz update.');
                $firestore->update('academy_quizzes', $quizId, ['published' => $_POST['published'] === '1']);
                $tab = 'quizzes';
                $message = $_POST['published'] === '1' ? 'Quiz published.' : 'Quiz unpublished.';
            } elseif ($action === 'save-assignment') {
                [$assignmentData, $validationErrors] = Assignment::validate($_POST);
                $tab = 'assignments';
                if ($validationErrors) { $message = reset($validationErrors); $error = true; }
                else {
                    $lesson = $firestore->get('academy_lessons', $assignmentData['lessonId']);
                    if (!$lesson) throw new RuntimeException('The selected lesson was not found.');
                    foreach ($firestore->listByField('academy_assignments', 'lessonId', $assignmentData['lessonId'], 10) as $existingAssignment) {
                        if (($existingAssignment['id'] ?? '') !== ($_POST['assignment_id'] ?? null)) throw new RuntimeException('This lesson already has an assignment. Edit the existing one instead.');
                    }
                    $assignmentData['courseId'] = (string) ($lesson['courseId'] ?? '');
                    $assignmentData['courseTitle'] = (string) ($lesson['courseTitle'] ?? 'Course');
                    $assignmentData['lessonTitle'] = (string) ($lesson['title'] ?? 'Lesson');
                    $editId = isset($_POST['assignment_id']) && is_string($_POST['assignment_id']) && $_POST['assignment_id'] !== '' ? $_POST['assignment_id'] : null;
                    Assignment::save($firestore, $assignmentData, $editId);
                    $message = $editId ? 'Assignment changes saved.' : 'Assignment added.';
                }
            } elseif ($action === 'assignment-publish' && isset($_POST['assignment_id'], $_POST['published'])) {
                $assignmentId = is_string($_POST['assignment_id']) ? $_POST['assignment_id'] : '';
                if (!preg_match('/^[A-Za-z0-9_-]{1,150}$/', $assignmentId) || !in_array((string) $_POST['published'], ['0', '1'], true)) throw new RuntimeException('Invalid assignment update.');
                $firestore->update('academy_assignments', $assignmentId, ['published' => $_POST['published'] === '1']);
                $tab = 'assignments';
                $message = $_POST['published'] === '1' ? 'Assignment published.' : 'Assignment unpublished.';
            } elseif ($action === 'review-submission' && isset($_POST['submission_id'], $_POST['score'])) {
                AssignmentSubmission::review($firestore, is_string($_POST['submission_id']) ? $_POST['submission_id'] : '', $_POST['score'], $_POST['feedback'] ?? '');
                $tab = 'submissions';
                $message = 'Submission review saved.';
            } elseif ($action === 'revoke-certificate' && isset($_POST['certificate_id'], $_POST['reason'])) {
                Certificate::revoke($firestore, is_string($_POST['certificate_id']) ? $_POST['certificate_id'] : '', $_POST['reason']);
                $tab = 'certificates';
                $message = 'Certificate revoked.';
            }
        } catch (Throwable $exception) {
            error_log('Admin action failed: ' . $exception->getMessage());
            $message = 'That action could not be completed.';
            $error = true;
        }
    }
}

if (!$middleware->authenticated()) $view = 'login';
$notificationCount = 0;
if ($middleware->authenticated()) {
    try {
        $notificationStore = new FirestoreService(FirebaseService::firestore());
        $notificationCount = count(array_filter($notificationStore->list('contact_inquiries', 100, null), static fn(array $inquiry): bool => strtolower((string) ($inquiry['status'] ?? 'open')) !== 'closed'));
        foreach (['academy_event_registrations', 'academy_webinar_registrations', 'academy_job_applications', 'academy_scholarship_applications', 'academy_partner_inquiries', 'academy_accessibility_reports'] as $featureCollection) $notificationCount += count($notificationStore->listByField($featureCollection, 'status', 'new', 100));
    } catch (Throwable $exception) {
        error_log('Admin notification count unavailable: ' . $exception->getMessage());
    }
}
$tabTitles = ['overview' => 'Control center', 'inquiries' => 'Course enquiries', 'public-submissions' => 'Public submissions', 'users' => 'Learner and instructor accounts', 'instructors' => 'Instructor oversight', 'subscribers' => 'Newsletter subscribers', 'courses' => 'Course catalogue', 'enrollments' => 'Course requests', 'payments' => 'Payments', 'lessons' => 'Course lessons', 'quizzes' => 'Quizzes', 'assignments' => 'Assignments', 'submissions' => 'Assignment submissions', 'activity' => 'Learner activity', 'certificates' => 'Certificates', 'pages' => 'Page introductions', 'settings' => 'Website and platform settings'];
$tabDescriptions = ['overview' => 'Manage the public website, online learning platform, staff and learner activity.', 'inquiries' => 'Review messages sent through the public contact form.', 'public-submissions' => 'Review event registrations, webinar registrations, career interests, scholarship applications, partnership enquiries and accessibility reports.', 'users' => 'Manage learner and instructor roles and account access.', 'instructors' => 'Review instructors, their assigned courses and the learners enrolled in those courses.', 'subscribers' => 'Manage subscription consent and opt-out requests.', 'courses' => 'Create courses, assign instructors and choose which are visible on the public site.', 'enrollments' => 'Review and approve learner requests.', 'payments' => 'Review Paystack checkout records and verified mobile money payments.', 'lessons' => 'Write and publish lessons for catalogue courses.', 'quizzes' => 'Create multiple-choice checks for published lesson content.', 'assignments' => 'Publish practical work for your lessons.', 'submissions' => 'Review learner work and provide scores and feedback.', 'activity' => 'Review completed lessons and quiz results.', 'certificates' => 'Review issued awards and revoke certificates when needed.', 'pages' => 'Edit the heading and introduction shown on key website and learning audience pages.', 'settings' => 'Set public contact details, the site identity, announcements and account registration.'];
require_once dirname(__DIR__, 2) . '/app/Views/staff/layouts/shell.php';
staff_page_start($view === 'login' ? 'Staff sign in' : ($tabTitles[$tab] ?? 'Academy dashboard'), 'admin', $view === 'login' ? 'overview' : $tab, $view === 'login' ? 'Sign in with your TechWorld Academy learning account to access administration.' : ($tabDescriptions[$tab] ?? 'Manage the academy.'), $notificationCount);
?>
<section class="section container admin-page">
  <?php if ($view === 'login'): ?>
    <div class="admin-login"><span class="eyebrow">Staff access</span><h1>Academy admin</h1><p>Sign in to review course enquiries and newsletter subscriptions.</p>
      <div class="admin-alert">Use your TechWorld Academy learning account. Accounts with the administrator role can open this dashboard.</div>
      <?php if ($message !== ''): ?><div class="admin-alert <?= $error ? 'is-error' : 'is-success' ?>" role="status"><?= e($message) ?></div><?php endif; ?>
      <?php if (!empty($_SESSION['learning_user_id']) && ($_SESSION['learning_user_role'] ?? '') !== 'admin'): ?><p>You are signed in with a learner or instructor account. Sign out to switch to the administrator learning account.</p><form method="post" action="/logout/"><input type="hidden" name="csrf_token" value="<?= e($_SESSION['csrf_token']) ?>"><button class="button button-primary" type="submit">Sign out and switch account</button></form><?php else: ?><a class="button button-primary" href="/login/?continue=%2Fadmin%2F">Sign in with learning account</a><?php endif; ?>
    </div>
  <?php else: ?>
    <div class="admin-content">
    <?php if ($message !== ''): ?><div class="admin-alert <?= $error ? 'is-error' : 'is-success' ?>" role="status"><?= e($message) ?></div><?php endif; ?>
    <?php if ($tab === 'overview'): ?>
      <?php try {
          $overviewStore = new FirestoreService(FirebaseService::firestore());
          $overviewUsers = $overviewStore->list('academy_users', 100, null);
          $overviewCourses = $overviewStore->list('academy_courses', 100, 'title', 'ASCENDING');
          $overviewRequests = $overviewStore->list('academy_enrollments', 100, null);
          $overviewInquiries = $overviewStore->list('contact_inquiries', 100, null);
          $overviewPayments = $overviewStore->list('academy_payments', 100, 'createdAt');
      } catch (Throwable $exception) {
          error_log('Admin overview metrics unavailable: ' . $exception->getMessage());
          $overviewUsers = $overviewCourses = $overviewRequests = $overviewInquiries = $overviewPayments = null;
      } ?>
      <div class="staff-metrics" aria-label="Academy record counts">
        <?php foreach ([['Learner & staff accounts', $overviewUsers], ['Managed courses', $overviewCourses], ['Enrollment requests', $overviewRequests], ['Website enquiries', $overviewInquiries], ['Payment records', $overviewPayments]] as [$metricLabel, $metricRows]): ?>
          <article class="staff-metric-card"><span><?= e($metricLabel) ?></span><strong><?= is_array($metricRows) ? number_format(count($metricRows)) : '&mdash;' ?></strong><small><?= is_array($metricRows) ? 'Records in current view (max 100)' : 'Temporarily unavailable' ?></small></article>
        <?php endforeach; ?>
        <?php $revenueByCurrency = []; foreach (is_array($overviewPayments) ? $overviewPayments : [] as $payment) if (($payment['status'] ?? '') === 'paid') { $currency = strtoupper((string) ($payment['currency'] ?? 'GHS')); if (preg_match('/^[A-Z]{3}$/', $currency)) $revenueByCurrency[$currency] = ($revenueByCurrency[$currency] ?? 0) + (int) ($payment['amountMinor'] ?? 0); } ?>
        <?php $revenueText = 'Unavailable'; if ($overviewPayments !== null) { $revenueText = '0.00 GHS'; if ($revenueByCurrency) { $revenueParts = []; foreach ($revenueByCurrency as $currency => $amountMinor) $revenueParts[] = number_format($amountMinor / 100, 2) . ' ' . $currency; $revenueText = implode(', ', $revenueParts); } } ?><article class="staff-metric-card"><span>Verified revenue</span><strong><?= e($revenueText) ?></strong><small>Paid records in the latest 100 payments</small></article>
      </div>
      <div class="admin-control-grid">
        <a href="/admin/?tab=courses"><span class="admin-control-icon">&#9670;</span><strong>Course catalogue</strong><p>Create, edit, publish and assign courses.</p><span>Manage courses &#8594;</span></a>
        <a href="/admin/?tab=lessons"><span class="admin-control-icon">&#9998;</span><strong>Learning content</strong><p>Manage lessons, quizzes and practical assignments.</p><span>Manage content &#8594;</span></a>
        <a href="/admin/?tab=users"><span class="admin-control-icon">&#9673;</span><strong>People and instructors</strong><p>Manage account roles and instructor access.</p><span>Manage accounts &#8594;</span></a>
        <a href="/admin/?tab=instructors"><span class="admin-control-icon">&#9733;</span><strong>Instructor oversight</strong><p>Review assigned courses, publishing status and enrolled learners.</p><span>Review instructors &#8594;</span></a>
        <a href="/admin/?tab=enrollments"><span class="admin-control-icon">&#8594;</span><strong>Enrollment requests</strong><p>Approve or decline course access requests.</p><span>Review requests &#8594;</span></a>
        <a href="/admin/?tab=submissions"><span class="admin-control-icon">&#10003;</span><strong>Assessment and learner work</strong><p>Grade assignment submissions and give feedback.</p><span>Review learner work &#8594;</span></a>
        <a href="/admin/?tab=activity"><span class="admin-control-icon">&#9711;</span><strong>Learner activity</strong><p>Review completed lessons and quiz results across the platform.</p><span>View activity &#8594;</span></a>
        <a href="/admin/?tab=certificates"><span class="admin-control-icon">&#9734;</span><strong>Certificates</strong><p>Review issued certificates and revoke awards when required.</p><span>Manage certificates &#8594;</span></a>
        <a href="/admin/?tab=inquiries"><span class="admin-control-icon">&#9993;</span><strong>Website enquiries</strong><p>Respond to contact messages and manage subscribers.</p><span>Open enquiries &#8594;</span></a>
        <a href="/admin/?tab=public-submissions"><span class="admin-control-icon">&#9745;</span><strong>Public form submissions</strong><p>Review event, webinar, scholarship, career and partnership submissions.</p><span>Open submissions &#8594;</span></a>
        <a href="/admin/?tab=subscribers"><span class="admin-control-icon">&#9998;</span><strong>Newsletter subscribers</strong><p>Review consent and process unsubscribe requests.</p><span>Manage subscribers &#8594;</span></a>
        <a href="/admin/?tab=settings"><span class="admin-control-icon">&#9881;</span><strong>Website settings</strong><p>Update site identity, contact details and public notices.</p><span>Open settings &#8594;</span></a>
        <a href="/admin/?tab=pages"><span class="admin-control-icon">&#9998;</span><strong>Page introductions</strong><p>Edit headings and introductory copy across the website and learning audience pages.</p><span>Edit page copy &#8594;</span></a>
      </div>
      <div class="admin-control-footer"><span>Public site</span><a href="<?= e(public_website_url('/')) ?>" target="_blank" rel="noopener noreferrer">Preview website &#8599;</a><span>Learning platform</span><a href="<?= e(learning_platform_url('/')) ?>" target="_blank" rel="noopener noreferrer">Preview learning catalogue &#8599;</a></div>
      <?php
        $today = new DateTimeImmutable('today');
        $weekDays = [];
        for ($dayOffset = 6; $dayOffset >= 0; $dayOffset--) $weekDays[$today->modify('-' . $dayOffset . ' days')->format('Y-m-d')] = 0;
        $dateValue = static function (array $row, array $fields): ?DateTimeImmutable {
            foreach ($fields as $field) {
                $value = $row[$field] ?? null;
                if ($value instanceof DateTimeInterface) return DateTimeImmutable::createFromInterface($value);
                if (is_string($value) && $value !== '') try { return new DateTimeImmutable($value); } catch (Throwable) {}
            }
            return null;
        };
        $weeklyEnrollmentCounts = $weekDays;
        foreach (is_array($overviewRequests) ? $overviewRequests : [] as $record) {
            $date = $dateValue($record, ['requestedAt', 'createdAt']);
            if ($date && isset($weeklyEnrollmentCounts[$date->format('Y-m-d')])) $weeklyEnrollmentCounts[$date->format('Y-m-d')]++;
        }
        $sortedEnrollments = is_array($overviewRequests) ? $overviewRequests : [];
        usort($sortedEnrollments, static function (array $a, array $b) use ($dateValue): int { return ($dateValue($b, ['requestedAt', 'createdAt'])?->getTimestamp() ?? 0) <=> ($dateValue($a, ['requestedAt', 'createdAt'])?->getTimestamp() ?? 0); });
        $sortedPayments = is_array($overviewPayments) ? $overviewPayments : [];
      ?>
      <div class="staff-chart-grid">
        <section class="staff-chart-card"><h2>Enrollment activity</h2><p>Requests created each day in the latest 7 days. Based on the latest 100 enrollment records.</p><div class="staff-bar-chart" role="img" aria-label="Daily enrollment request counts for the last seven days">
